const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || args.instruction || '').trim();
const content = String(source.content || args.content || payload.content || '').trim() || rawText;
let docId = String(source.documentId || source.docId || source.targetId || args.documentId || args.docId || args.targetId || payload.documentId || payload.docId || payload.targetId || '').trim();
let docName = String(source.docName || source.targetName || source.fileName || args.docName || args.targetName || args.fileName || payload.docName || payload.targetName || payload.fileName || '').trim();
if (!docName && rawText) {
  const splitIndex = rawText.indexOf(':');
  if (splitIndex > 0) {
    docName = rawText.slice(0, splitIndex).trim();
  }
}
const hasTarget = Boolean(docId || docName);
return [{ json: { ...source, payload, message, chatId, rawText, content, docId, documentId: docId, targetId: docId, docName, targetName: docName, hasTarget, response: hasTarget && content ? '' : 'Mia cần tên/id tài liệu và nội dung mới để cập nhật.' } }];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, ok: false, response: `Mia chưa tìm thấy Google Doc phù hợp: ${source.docName || source.query || ''}` } }];
}
const doc = rows[0];
return [{ json: { ...source, ok: true, docId: doc.id || source.docId || '', targetId: doc.id || source.targetId || source.docId || '', docName: doc.name || source.docName || source.targetName || '', targetName: doc.name || source.targetName || source.docName || '', webViewLink: doc.webViewLink || '' } }];

const source = $('Prepare Action').item.json || {};
const doc = $('Docs Get Document').item.json || {};
const content = String(source.content || '').trim();
if (!content) {
  throw new Error('Missing content. Cannot update Google Docs document with empty content.');
}
const bodyContent = Array.isArray(doc.body?.content) ? doc.body.content : [];
const requests = [];
if (bodyContent.length) {
  const last = bodyContent[bodyContent.length - 1];
  const endIndex = Number(last?.endIndex || 0);
  if (endIndex > 2) {
    requests.push({ deleteContentRange: { range: { startIndex: 1, endIndex: endIndex - 1 } } });
  }
}
requests.push({ insertText: { location: { index: 1 }, text: content } });
return [{ json: { ...source, documentId: source.documentId || source.docId || doc.documentId || '', body: { requests } } }];

const source = $('Prepare Action').item.json || {};
const result = $json || {};
const docId = source.docId || source.documentId || source.targetId || result.documentId || '';
const docName = source.docName || source.targetName || 'Không rõ tên';
const link = source.webViewLink || (docId ? `https://docs.google.com/document/d/${docId}/edit` : '');
const chars = String(source.content || '').length;
let text = `Đã cập nhật Google Doc: ${docName}`;
if (docId) text += `\nID: ${docId}`;
text += `\nSố ký tự mới: ${chars}`;
if (link) text += `\nMở tài liệu: ${link}`;
return [{ json: { chatId: source.chatId || '', text: text.trim(), docId, webViewLink: link } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target = source.subject || source.sender || source.query || source.messageId || source.id || '';
let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
